def score(dr,dc,src,src0,dst0):
    match=miss=extra=0
    H,W=g.shape
    for r in range(src0,src0+7):
        for c in range(29):
            if g[r,c]==8:
                rr,cc=r-src0+dst0+dr, c+dc
                if 0<=rr<H and 0<=cc<W:
                    if g[rr,cc]==8: match+=1
                    else: miss+=1
    return match,miss
